package main

import (
	"encoding/json"
	"net/http"
	"os"
)

type Item struct {
	ID   int    `json:"id"`
	Name string `json:"name"`
}

var (
	items  []Item
	nextID = 1
)

const swaggerHTML = `<!DOCTYPE html><html><head><title>API Docs</title><link rel="stylesheet" href="https://unpkg.com/swagger-ui-dist@3/swagger-ui.css"></head><body><div id="swagger-ui"></div><script src="https://unpkg.com/swagger-ui-dist@3/swagger-ui-bundle.js"></script><script>SwaggerUIBundle({url:"/api-docs.json",dom_id:"#swagger-ui"})</script></body></html>`

func main() {
	port := os.Getenv("PORT")
	if port == "" { port = "3000" }

	spec := map[string]interface{}{
		"openapi": "3.0.0",
		"info":    map[string]string{"title": "Test API", "version": "1.0.0"},
		"paths": map[string]interface{}{
			"/items": map[string]interface{}{
				"get": map[string]interface{}{
					"summary": "List items",
					"responses": map[string]interface{}{
						"200": map[string]string{"description": "OK"},
					},
				},
				"post": map[string]interface{}{
					"summary": "Create item",
					"requestBody": map[string]interface{}{
						"required": true,
						"content": map[string]interface{}{
							"application/json": map[string]interface{}{
								"schema": map[string]interface{}{
									"type": "object",
									"properties": map[string]interface{}{
										"name": map[string]string{"type": "string"},
									},
								},
							},
						},
					},
					"responses": map[string]interface{}{
						"201": map[string]string{"description": "Created"},
					},
				},
			},
		},
	}

	http.HandleFunc("/items", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if r.Method == "GET" {
			json.NewEncoder(w).Encode(items)
		} else if r.Method == "POST" {
			var body struct{ Name string `json:"name"` }
			json.NewDecoder(r.Body).Decode(&body)
			item := Item{ID: nextID, Name: body.Name}
			nextID++
			items = append(items, item)
			w.WriteHeader(http.StatusCreated)
			json.NewEncoder(w).Encode(item)
		}
	})

	http.HandleFunc("/api-docs.json", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(spec)
	})

	http.HandleFunc("/api-docs", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/html")
		w.Write([]byte(swaggerHTML))
	})

	http.ListenAndServe(":"+port, nil)
}
